import sys
from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_bst_from_level_order(level_order):
    if not level_order or level_order[0] == 'null':
        return None

    root = TreeNode(int(level_order[0]))
    queue = deque([root])
    i = 1

    while queue and i < len(level_order):
        node = queue.popleft()

        if i < len(level_order) and level_order[i] != 'null':
            node.left = TreeNode(int(level_order[i]))
            queue.append(node.left)
        i += 1

        if i < len(level_order) and level_order[i] != 'null':
            node.right = TreeNode(int(level_order[i]))
            queue.append(node.right)
        i += 1

    return root

def insert_into_bst(root, val):
    if not root:
        return TreeNode(val)

    if val < root.val:
        root.left = insert_into_bst(root.left, val)
    else:
        root.right = insert_into_bst(root.right, val)

    return root

def level_order_traversal(root):
    if not root:
        return []

    result = []
    queue = deque([root])

    while queue:
        node = queue.popleft()
        if node:
            result.append(str(node.val))
            queue.append(node.left)
            queue.append(node.right)
        else:
            result.append('null')

    # Remove trailing nulls
    while result and result[-1] == 'null':
        result.pop()

    return result

def main():
    lines = sys.stdin.read().strip().split('\n')
    if len(lines) < 2:
        return

    level_order = lines[0].strip().split()
    insert_val = int(lines[1].strip())

    root = build_bst_from_level_order(level_order)
    root = insert_into_bst(root, insert_val)

    result = level_order_traversal(root)
    print(' '.join(result))

if __name__ == "__main__":
    main()
